/**
 * SortableJS 1.15.x (Stub)
 * 
 * JavaScript library for reorderable drag-and-drop lists.
 * This is a simplified stub for the catalog.
 * 
 * For production, download from:
 * https://cdn.jsdelivr.net/npm/sortablejs@latest/Sortable.min.js
 */

(function(global) {
  'use strict';

  function Sortable(el, options) {
    this.el = el;
    this.options = options || {};
    this.init();
  }

  Sortable.prototype.init = function() {
    var self = this;
    var items = this.el.children;

    Array.from(items).forEach(function(item) {
      item.draggable = true;

      item.addEventListener('dragstart', function(e) {
        e.dataTransfer.setData('text/plain', '');
        item.classList.add('sortable-dragging');
        self.draggedItem = item;
        
        if (self.options.onStart) {
          self.options.onStart({ item: item });
        }
      });

      item.addEventListener('dragend', function(e) {
        item.classList.remove('sortable-dragging');
        self.draggedItem = null;
        
        if (self.options.onEnd) {
          self.options.onEnd({ item: item });
        }
      });

      item.addEventListener('dragover', function(e) {
        e.preventDefault();
        if (self.draggedItem && self.draggedItem !== item) {
          var rect = item.getBoundingClientRect();
          var midY = rect.top + rect.height / 2;
          
          if (e.clientY < midY) {
            item.parentNode.insertBefore(self.draggedItem, item);
          } else {
            item.parentNode.insertBefore(self.draggedItem, item.nextSibling);
          }
        }
      });
    });
  };

  Sortable.create = function(el, options) {
    return new Sortable(el, options);
  };

  global.Sortable = Sortable;

  console.log('[Project Hub] Sortable stub loaded.');

})(typeof window !== 'undefined' ? window : this);
